import type { BuildTaskContextInput, BuildTaskContextPorts, BuildTaskContextResult } from './taskContextPorts';
import type { Project } from '../domain/Project';
import { createContextManifest } from '../domain/ContextManifest';
import { evaluateBudget } from '../domain/ContextBudget';
import { createCandidateFile } from '../domain/CandidateFile';
import {
  validateAndGetFiles,
  findDependencies,
  findRelatedTests,
  collectRecommendations,
  findRepositoryRules,
  type DiscoveredContextItem,
} from './TaskContextExplorer';
import { assembleContextEntries } from './TaskContextAssembler';

export class BuildTaskContextUseCase {
  constructor(private readonly ports: BuildTaskContextPorts) {}

  async execute(input: BuildTaskContextInput): Promise<BuildTaskContextResult> {
    const { taskContext } = input;
    const project = await this.getProject(taskContext.projectId);
    const allFiles = await validateAndGetFiles(project, this.ports.files, taskContext.entryPoints);
    const { items, warnings } = await this.discoverAll(project, taskContext.entryPoints, allFiles);

    const entries = assembleContextEntries(project.id, items, taskContext.entryPoints);
    const totalBytes = calculateTotalBytes(entries, allFiles);
    const budget = evaluateBudget(totalBytes, input.tokenLimit ?? 40000);
    const manifest = createContextManifest(project.id, taskContext.task, taskContext.entryPoints, entries, budget);
    return { manifest, warnings };
  }

  private async discoverAll(
    project: Project,
    entryPoints: readonly string[],
    allFiles: readonly { relativePath: string; size: number }[]
  ) {
    const targetItems = toTargetItems(project.id, entryPoints);
    const depItems = await findDependencies(project, entryPoints, this.ports.fileContent, this.ports.dependencyScanner);
    const testItems = findRelatedTests(project, entryPoints, allFiles);
    const { items: recItems, warnings } = await collectRecommendations(project, entryPoints, this.ports.recommendations);
    const ruleItems = findRepositoryRules(project, allFiles);
    return { items: [...targetItems, ...depItems, ...testItems, ...recItems, ...ruleItems], warnings };
  }

  private async getProject(projectId: string) {
    const projects = await this.ports.projects.getByIds([projectId]);
    const project = projects[0];
    if (!project) throw new Error(`Project not found: ${projectId}`);
    return project;
  }
}

const toTargetItems = (projectId: string, entryPoints: readonly string[]): readonly DiscoveredContextItem[] =>
  entryPoints.map(ep => ({
    candidate: createCandidateFile(projectId, ep, ['pathAffinity']),
    recommendationReasons: [],
  }));

const calculateTotalBytes = (
  entries: readonly { relativePath: string }[],
  allFiles: readonly { relativePath: string; size: number }[]
): number => {
  const sizeMap = new Map(allFiles.map(f => [f.relativePath.replace(/\\/g, '/').toLowerCase(), f.size]));
  let sum = 0;
  for (const e of entries) {
    sum += sizeMap.get(e.relativePath.replace(/\\/g, '/').toLowerCase()) ?? 1000;
  }
  return sum;
};

import type { CandidateFile } from '../domain/CandidateFile';
import { evaluateBudget } from '../domain/ContextBudget';
import type { PackMode } from '../domain/PackMode';
import type { Project } from '../domain/Project';
import { DesktopOutputBuilder, type DesktopOutputSelection } from './DesktopOutputBuilder';
import { SkeletonService } from '../../engine/domain/SkeletonService';
import { DependencyScanner } from '../../engine/application/DependencyScanner';
import type {
  AnalysisWarning,
  BuildDesktopContextInput,
  BuildDesktopContextPorts,
  BuildDesktopContextResult,
  DesktopContextFile,
} from './ports';

export class BuildDesktopContextUseCase {
  constructor(private readonly ports: BuildDesktopContextPorts) {}

  async build(input: BuildDesktopContextInput): Promise<BuildDesktopContextResult> {
    const projects = await this.ports.projects.getByIds(projectIds(input.candidates));
    const mode = input.packMode ?? 'full';
    const output = await getOutput(input, projects, this.ports.fileContent, mode);
    const preview = getPreview(input, output.files, this.ports.formatter, mode);
    const budget = evaluateBudget(new TextEncoder().encode(preview).byteLength, input.tokenLimit ?? Number.MAX_SAFE_INTEGER);
    const manifest = input.candidates.map(c => ({
      projectId: c.projectId,
      relativePath: c.relativePath,
      included: output.files.some(f => f.relativePath === c.relativePath || f.relativePath.startsWith(`${c.relativePath}:`)),
      reasons: c.reasons
    }));
    if (!budget.withinLimit) return { preview: '', warnings: [...output.warnings, budgetWarning()], budget, manifest };
    return { preview, warnings: output.warnings, budget, manifest };
  }
}

const getOutput = async (
  input: BuildDesktopContextInput,
  projects: readonly Project[],
  fileContent: BuildDesktopContextPorts['fileContent'],
  mode: PackMode
): Promise<DesktopOutputSelection> => {
  if (mode === 'directoryTree') return { files: [], warnings: [] };
  const builder = new DesktopOutputBuilder(fileContent, new SkeletonService(), new DependencyScanner());
  return builder.build(input.candidates, projects, input.maxFileSizeKB, mode, input.includeDependencies, input.tokenLimit, input.autoOptimize);
};

const getPreview = (
  input: BuildDesktopContextInput,
  files: readonly DesktopContextFile[],
  formatter: BuildDesktopContextPorts['formatter'],
  mode: PackMode
): string =>
  mode === 'directoryTree'
    ? input.candidates.map(c => c.relativePath).join('\n')
    : formatter.format({ format: input.format, files });

const projectIds = (candidates: readonly CandidateFile[]): readonly string[] =>
  [...new Set(candidates.map(candidate => candidate.projectId))];

const budgetWarning = (): AnalysisWarning => ({
  kind: 'oversizedFile',
  projectId: 'workspace',
  message: 'The generated context exceeds the token budget.'
});


// src/features/repository-context/domain/ContextManifest.ts
import type { ProjectId } from './Project';
import type { ContextBudget } from './ContextBudget';
import type { ContextEntry } from './ContextEntry';
import type { CandidateEvidence } from './CandidateEvidence';

export type ContextManifest = Readonly<{
  projectId: ProjectId;
  task: string;
  entryPoints: readonly string[];
  entries: readonly ContextEntry[];
  budget: ContextBudget;
  evidences?: readonly CandidateEvidence[];
}>;

export const createContextManifest = (
  projectId: ProjectId,
  task: string,
  entryPoints: readonly string[],
  entries: readonly ContextEntry[],
  budget: ContextBudget,
  evidences?: readonly CandidateEvidence[]
): ContextManifest => Object.freeze({
  projectId,
  task,
  entryPoints: Object.freeze([...entryPoints]),
  entries: Object.freeze([...entries]),
  budget,
  ...(evidences && evidences.length > 0 ? { evidences: Object.freeze([...evidences]) } : {}),
});

// src/features/repository-context/infrastructure/formatting/ContextManifestFormatter.ts
import type { ContextManifest } from '../../domain/ContextManifest';
import type { ContextEntry } from '../../domain/ContextEntry';
import type { CandidateEvidence } from '../../domain/CandidateEvidence';

export const formatContextManifest = (manifest: ContextManifest): string => {
  const sections = [
    '# Context Manifest',
    formatTask(manifest.task),
    formatEntryPoints(manifest.entryPoints),
    formatContextTable(manifest.entries),
    formatBudget(manifest.budget),
  ];
  if (manifest.evidences && manifest.evidences.length > 0) {
    sections.push(formatEvidences(manifest.evidences));
  }
  return sections.join('\n\n') + '\n';
};

const formatTask = (task: string): string => `## Task\n\n${task}`;

const formatEntryPoints = (entryPoints: readonly string[]): string => {
  const list = entryPoints.map((ep) => `- ${ep}`).join('\n');
  return `## Entry Points\n\n${list}`;
};

const formatContextTable = (entries: readonly ContextEntry[]): string => {
  const header = '| Role | File | Score | Pack Mode | Reasons |\n|---|---|---:|---|---|';
  const rows = entries.map(formatTableRow).join('\n');
  return `## Context\n\n${header}\n${rows}`;
};

const formatTableRow = (entry: ContextEntry): string => {
  const reasons = formatReasons(entry);
  return `| ${entry.role} | ${entry.relativePath} | ${entry.score} | ${entry.packMode} | ${reasons} |`;
};

const formatReasons = (entry: ContextEntry): string => {
  if (entry.role === 'target') return 'target';
  const cand = entry.candidateReasons ?? [];
  const rec = (entry.recommendationReasons ?? []).map((r) => r.source);
  const combined = Array.from(new Set([...cand, ...rec]));
  return combined.length > 0 ? combined.join(', ') : '-';
};

const formatBudget = (budget: ContextManifest['budget']): string => {
  const within = budget.withinLimit ? 'yes' : 'no';
  return `## Budget\n\n- Bytes: ${budget.bytes}\n- Estimated tokens: ${budget.estimatedTokens}\n- Limit: ${budget.limit}\n- Within limit: ${within}`;
};

const formatEvidences = (evidences: readonly CandidateEvidence[]): string => {
  const byCandidate = groupEvidencesByCandidate(evidences);
  const blocks: string[] = ['## Candidate Evidence'];
  for (const [candidate, items] of byCandidate.entries()) {
    blocks.push(`### ${candidate}\n\nStructural support:\n${items.join('\n')}`);
  }
  return blocks.join('\n\n');
};

const groupEvidencesByCandidate = (
  evidences: readonly CandidateEvidence[]
): Map<string, string[]> => {
  const byCandidate = new Map<string, string[]>();
  for (const ev of evidences) {
    const list = byCandidate.get(ev.candidatePath) ?? [];
    const target = ev.relatedPath ?? ev.relatedSymbol ?? '';
    const line = ev.startLine ? `:L${ev.startLine}` : '';
    const item = `- ${ev.kind}: ${target}${line}`;
    list.push(item);
    byCandidate.set(ev.candidatePath, list);
  }
  return byCandidate;
};

import type { AnalyzedCandidate } from '../../../../src/features/repository-context/application/ports';

export type BudgetSummary = Readonly<{ label: string; over: boolean; ratio: number }>;

export const candidateKey = (projectId: string, relativePath: string): string =>
    `${projectId}:${relativePath.replace(/\\/g, '/')}`;

export const estimateTokens = (bytes: number): number =>
    Number.isFinite(bytes) && bytes > 0 ? Math.ceil(bytes / 4) : 0;

export const formatTokens = (tokens: number): string => {
    const safeTokens = Number.isFinite(tokens) && tokens >= 0 ? tokens : 0;
    return safeTokens >= 1000 ? `${(safeTokens / 1000).toFixed(1)}k` : `${safeTokens}`;
};

export const selectedTokenTotal = (
    candidates: readonly AnalyzedCandidate[],
    selectedKeys: readonly string[],
): number => candidates.reduce(
    (sum, candidate) => selectedKeys.includes(candidateKey(candidate.projectId, candidate.relativePath)) && candidate.size !== undefined
        ? sum + estimateTokens(candidate.size)
        : sum,
    0,
);

export const budgetSummary = (selectedTokens: number, limit: number): BudgetSummary => {
    const safeSelectedTokens = Number.isFinite(selectedTokens) && selectedTokens > 0 ? selectedTokens : 0;
    const hasValidLimit = Number.isFinite(limit) && limit > 0;
    return {
        label: `~${formatTokens(safeSelectedTokens)} / ${formatTokens(limit)} tokens`,
        over: hasValidLimit ? safeSelectedTokens > limit : safeSelectedTokens > 0,
        ratio: hasValidLimit ? Math.min(safeSelectedTokens / limit, 1) : safeSelectedTokens > 0 ? 1 : 0,
    };
};
import { describe, it, expect } from 'vitest';
import { budgetSummary, candidateKey, estimateTokens, formatTokens, selectedTokenTotal } from './tokenBudget';
import type { AnalyzedCandidate } from '../../../../src/features/repository-context/application/ports';

const candidate = (projectId: string, relativePath: string, size: number | undefined): AnalyzedCandidate => ({
    projectId, relativePath, reasons: ['pathAffinity'], excluded: false, score: 0, size,
});

describe('tokenBudget', () => {
    it('estimates 1 token per 4 bytes rounding up', () => {
        expect(estimateTokens(0)).toBe(0);
        expect(estimateTokens(1)).toBe(1);
        expect(estimateTokens(400)).toBe(100);
        expect(estimateTokens(401)).toBe(101);
    });
    it('treats invalid byte counts as zero tokens', () => {
        expect(estimateTokens(-1)).toBe(0);
        expect(estimateTokens(Number.NaN)).toBe(0);
        expect(estimateTokens(Number.POSITIVE_INFINITY)).toBe(0);
    });
    it('formats thousands with a k suffix', () => {
        expect(formatTokens(999)).toBe('999');
        expect(formatTokens(1000)).toBe('1.0k');
        expect(formatTokens(1500)).toBe('1.5k');
    });
    it('sums tokens for selected candidates only', () => {
        const candidates = [
            candidate('p1', 'a.ts', 400),
            candidate('p1', 'b.ts', 800),
            candidate('p1', 'c.ts', undefined),
        ];
        expect(selectedTokenTotal(candidates, ['p1:a.ts'])).toBe(100);
        expect(selectedTokenTotal(candidates, ['p1:c.ts'])).toBe(0);
    });
    it('matches Windows candidate paths with POSIX selected keys', () => {
        const candidates = [candidate('p1', 'src\\auth.ts', 400)];

        expect(candidateKey('p1', 'src\\auth.ts')).toBe('p1:src/auth.ts');
        expect(selectedTokenTotal(candidates, ['p1:src/auth.ts'])).toBe(100);
    });
    it('flags over budget when selected tokens exceed the limit', () => {
        expect(budgetSummary(120, 100)).toMatchObject({ over: true, ratio: 1 });
        expect(budgetSummary(50, 100)).toMatchObject({ over: false, ratio: 0.5 });
        expect(budgetSummary(100, 100)).toMatchObject({ over: false, ratio: 1 });
        expect(budgetSummary(120, 0)).toMatchObject({ over: true, ratio: 1 });
        expect(budgetSummary(0, 0)).toMatchObject({ over: false, ratio: 0 });
        expect(budgetSummary(50, -1)).toMatchObject({ over: true, ratio: 1 });
        expect(budgetSummary(50, Number.NaN)).toMatchObject({ over: true, ratio: 1 });
        expect(budgetSummary(50, Number.POSITIVE_INFINITY)).toMatchObject({ over: true, ratio: 1 });
        expect(budgetSummary(0, Number.NaN)).toMatchObject({ over: false, ratio: 0 });
        expect(budgetSummary(50, 100).label).toBe('~50 / 100 tokens');
    });
    it('treats non-positive and non-finite selected tokens as zero', () => {
        for (const selectedTokens of [Number.NaN, -1, Number.POSITIVE_INFINITY]) {
            expect(budgetSummary(selectedTokens, 100)).toEqual({
                label: '~0 / 100 tokens', over: false, ratio: 0,
            });
        }
    });
});

export type ContextBudget = Readonly<{
  bytes: number;
  estimatedTokens: number;
  limit: number;
  withinLimit: boolean;
}>;

export const evaluateBudget = (bytes: number, limit: number): ContextBudget => {
  const estimatedTokens = Math.ceil(bytes / 4);
  return { bytes, estimatedTokens, limit, withinLimit: estimatedTokens <= limit };
};
